      "path": "plugins/deepseek-harness-flowx/cordis.patch.yml",
      "content": "# SPDX-FileCopyrightText: 2026 FlowX contributors\n# SPDX-License-Identifier: Apache-2.0\n# FlowX-Origin: urn:uuid:ea62b8c8-902a-4eb4-a42e-e5412ed08466\n# Upstream: https://github.com/AIpRoBuilder/FlowX\n# Added 2026-11-09: register the FlowX Harness host and browser package.\n- insert:\n    - id: flowx\n      name: dsh-flowx-plugin"
